create table if not exists public.staff_todos(id uuid primary key default gen_random_uuid(),title text not null check(char_length(trim(title)) between 1 and 250),notes text not null default'',priority text not null default'MEDIUM' check(priority in('LOW','MEDIUM','HIGH')),due_at timestamptz,completed_at timestamptz,assigned_to uuid not null references public.staff_profiles(id),created_by uuid not null references public.staff_profiles(id),position integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.staff_todo_activity(id bigint generated always as identity primary key,todo_id uuid references public.staff_todos(id) on delete set null,actor_id uuid not null references public.staff_profiles(id),action text not null,details jsonb not null default'{}',created_at timestamptz not null default now());
alter table public.staff_todos enable row level security;alter table public.staff_todo_activity enable row level security;
alter table public.staff_profiles drop constraint if exists staff_profiles_desktop_modules_check;
alter table public.staff_profiles add constraint staff_profiles_desktop_modules_check check(desktop_modules is null or desktop_modules <@ array['dashboard','leads','students','counselling','applications','b2b','classes','mocks','documents','finance','reports','hrms','settings','messages','assignments','todos']::text[]);
insert into public.permissions(role,permission_name,enabled) select role,permission_name,true from(values('ADMIN'::public.staff_role),('DIRECTOR'))r(role) cross join(values('todos.use'),('todos.manage'),('todos.audit'))p(permission_name) on conflict(role,permission_name)do update set enabled=true;
update public.staff_profiles set desktop_modules=array_append(desktop_modules,'todos') where role in('ADMIN','DIRECTOR') and desktop_modules is not null and not('todos'=any(desktop_modules));
drop policy if exists staff_todos_read on public.staff_todos;create policy staff_todos_read on public.staff_todos for select to authenticated using(public.has_permission('todos.audit') or (public.has_permission('todos.use') and assigned_to=auth.uid()) or created_by=auth.uid());
drop policy if exists staff_todo_activity_audit on public.staff_todo_activity;create policy staff_todo_activity_audit on public.staff_todo_activity for select to authenticated using(public.has_permission('todos.audit'));
create or replace function public.save_staff_todo(payload jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare tid uuid;target uuid:=coalesce(nullif(payload->>'assigned_to','')::uuid,auth.uid());begin if not public.has_permission('todos.use') and not public.has_permission('todos.manage')then raise exception'To-do permission required';end if;if target<>auth.uid()and not public.has_permission('todos.manage')then raise exception'To-do assignment permission required';end if;insert into staff_todos(title,notes,priority,due_at,assigned_to,created_by,position)values(trim(payload->>'title'),coalesce(payload->>'notes',''),coalesce(payload->>'priority','MEDIUM'),nullif(payload->>'due_at','')::timestamptz,target,auth.uid(),extract(epoch from now())::integer)returning id into tid;insert into staff_todo_activity(todo_id,actor_id,action,details)values(tid,auth.uid(),'CREATED',jsonb_build_object('assigned_to',target));return tid;end$$;
create or replace function public.update_staff_todo(todo_uuid uuid,payload jsonb)returns void language plpgsql security definer set search_path=public as $$declare old staff_todos;begin select*into old from staff_todos where id=todo_uuid;if old.id is null then raise exception'To-do not found';end if;if old.assigned_to<>auth.uid()and old.created_by<>auth.uid()and not public.has_permission('todos.manage')then raise exception'Not authorized';end if;update staff_todos set title=coalesce(nullif(trim(payload->>'title'),''),title),notes=coalesce(payload->>'notes',notes),priority=coalesce(payload->>'priority',priority),due_at=case when payload?'due_at'then nullif(payload->>'due_at','')::timestamptz else due_at end,completed_at=case when payload?'completed'then case when(payload->>'completed')::boolean then now()else null end else completed_at end,position=coalesce((payload->>'position')::integer,position),updated_at=now()where id=todo_uuid;insert into staff_todo_activity(todo_id,actor_id,action,details)values(todo_uuid,auth.uid(),case when payload?'completed'then case when(payload->>'completed')::boolean then'COMPLETED'else'REOPENED'end else'UPDATED'end,payload);end$$;
create or replace function public.delete_staff_todo(todo_uuid uuid)returns void language plpgsql security definer set search_path=public as $$declare old staff_todos;begin select*into old from staff_todos where id=todo_uuid;if old.created_by<>auth.uid()and not public.has_permission('todos.manage')then raise exception'Not authorized';end if;insert into staff_todo_activity(todo_id,actor_id,action,details)values(todo_uuid,auth.uid(),'DELETED',jsonb_build_object('title',old.title));delete from staff_todos where id=todo_uuid;end$$;
revoke all on function public.save_staff_todo(jsonb),public.update_staff_todo(uuid,jsonb),public.delete_staff_todo(uuid)from public;grant execute on function public.save_staff_todo(jsonb),public.update_staff_todo(uuid,jsonb),public.delete_staff_todo(uuid)to authenticated;
